// Uma linha da planilha por INSCRITO — de QUALQUER live.
//
// Este workflow e' o PADRAO: a MESMA URL de webhook serve todas as LPs de
// live. O que separa uma live da outra nao e' um workflow por destino, e' a
// coluna "Destino" (o campo `slug` do payload).
//
// ⚠️ Nomes das chaves = nomes das COLUNAS. O no do Sheets mapeia por NOME, e
// coluna que nao existe no cabecalho da linha 1 e' DESCARTADA EM SILENCIO --
// nao da erro, o dado simplesmente some. Cabecalho exato esperado:
//
//   Data/hora | Destino | Nome | WhatsApp | E-mail | Live | Formulario | Origem | gclid | fbclid | lead_id

const linhas = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const txt = (v) => String(v ?? '').trim();

  const whatsapp = txt(b.whatsapp);
  // Telefone como TEXTO: sem o apostrofo o Sheets come o '+' e transforma
  // +5511987654321 em notacao cientifica. E telefone quebrado nao dispara no
  // ManyChat.
  const whatsappCelula = whatsapp ? `'${whatsapp}` : '';

  const origem = [b.utm_source, b.utm_medium, b.utm_campaign, b.utm_content]
    .filter(Boolean)
    .join(' / ');

  linhas.push({
    json: {
      'Data/hora': txt(b.data_hora_cadastro),
      // 'japao-live' | 'peru-live' | ...
      // ⚠️ E' por esta coluna que voce FILTRA antes de disparar no ManyChat.
      // Sem filtro, quem se inscreveu no Peru recebe o aviso da live do Japao.
      'Destino': txt(b.slug) || 'desconhecido',
      'Nome': txt(b.nome),
      // Cada live escolhe os campos que pede (live.formulario nas LPs): a do
      // Japao pede WhatsApp, a do Peru pede e-mail. A coluna que a live NAO
      // pediu vem vazia -- isso e' esperado, nao e' falha de captura.
      'WhatsApp': whatsappCelula,
      'E-mail': txt(b.email).toLowerCase(),
      'Live': txt(b.evento_titulo),
      'Formulario': b.posicao === 'fim' ? 'fim da pagina' : 'topo da pagina',
      'Origem': origem,
      'gclid': txt(b.gclid),
      'fbclid': txt(b.fbclid),
      'lead_id': txt(b.lead_id),
    },
  });
}

return linhas;

// Uma linha da planilha por pessoa que ENTROU na sala — de QUALQUER live.
//
// O payload vem de /api/entrar-live. Mesma ideia do de cima: uma URL so' para
// todas as lives, separadas pela coluna "Destino".
//
// ⚠️ Cabecalho exato esperado na linha 1 (SEM a coluna Formulario, que so'
// existe na planilha de inscritos):
//
//   Data/hora | Destino | Nome | WhatsApp | E-mail | Live | Origem | gclid | fbclid | lead_id

const linhas = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const txt = (v) => String(v ?? '').trim();

  const whatsapp = txt(b.whatsapp);
  // Telefone como TEXTO: sem o apostrofo o Sheets come o '+' e transforma
  // +5511987654321 em notacao cientifica.
  const whatsappCelula = whatsapp ? `'${whatsapp}` : '';

  const origem = [b.utm_source, b.utm_medium, b.utm_campaign, b.utm_content]
    .filter(Boolean)
    .join(' / ');

  linhas.push({
    json: {
      // `data_hora_entrada` e' o campo do /api/entrar-live. O fallback para
      // `data_hora_cadastro` existe porque um payload de INSCRICAO disparado
      // aqui por engano (ou por pin de teste) deixaria a coluna vazia, e uma
      // linha sem data e' inutil para cruzar inscritos x presentes.
      'Data/hora': txt(b.data_hora_entrada) || txt(b.data_hora_cadastro),
      'Destino': txt(b.slug) || 'desconhecido',
      'Nome': txt(b.nome),
      'WhatsApp': whatsappCelula,
      'E-mail': txt(b.email).toLowerCase(),
      'Live': txt(b.evento_titulo),
      'Origem': origem,
      'gclid': txt(b.gclid),
      'fbclid': txt(b.fbclid),
      'lead_id': txt(b.lead_id),
    },
  });
}

return linhas;
